class Solution {
 bool adjacent(char a,char b){return abs(a-b)==1||abs(a-b)==25;}
public:
 string lexicographicallySmallestString(string s){
  int n=s.size();vector<vector<char>> erase(n+1,vector<char>(n+1));
  for(int i=0;i<=n;++i)erase[i][i]=1;
  for(int len=2;len<=n;len+=2)for(int l=0;l+len<=n;++l){int r=l+len;
   for(int j=l+1;j<r;j+=2)if(adjacent(s[l],s[j])&&erase[l+1][j]&&erase[j+1][r]){erase[l][r]=1;break;}
  }
  vector<string> dp(n+1);dp[n]="";
  for(int i=n-1;i>=0;--i){dp[i]=s.substr(i,1)+dp[i+1];
   for(int j=i+1;j<n;++j)if(adjacent(s[i],s[j])&&erase[i+1][j]){
    string cand=dp[j+1];if(cand<dp[i])dp[i]=cand;
   }
  }
  return dp[0];
 }
};
